CREATE OR REPLACE FUNCTION public.sgp_admin_rol_accesos_guardar(p_token text, p_rol text, p_accesos text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if not exists(
   select 1 from sgp_sesiones_app s join sgp_usuarios u on u.id_usuario=s.id_usuario
   where s.token_hash=encode(extensions.digest(coalesce(p_token,''),'sha256'),'hex')
     and s.revocado_en is null and s.expira_en>now() and u.activo=true and u.rol='ADMINISTRADOR'
 ) then raise exception 'Sin permisos'; end if;
 delete from sgp_rol_accesos where rol=p_rol;
 insert into sgp_rol_accesos(rol,ventana,permitido)
 select p_rol,x,true from unnest(coalesce(p_accesos,array[]::text[])) x;
end $function$

CREATE OR REPLACE FUNCTION public.sgp_admin_usuario_guardar(p_token text, p_id_usuario uuid, p_usuario text, p_nombre text, p_rol text, p_password text, p_activo boolean, p_accesos text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare admin text; uid uuid; vrol text:=upper(trim(p_rol));
begin
 admin:=sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR']);
 if trim(coalesce(p_usuario,''))='' or trim(coalesce(p_nombre,''))='' then raise exception 'Usuario y nombre son obligatorios'; end if;
 if vrol not in('COORDINADOR','LIDER MECANIZADO','LIDER LINEA','RECEPCION','PATINADOR','PICKING','SUPERVISOR DE PICKING','CONSULTA','ADMINISTRADOR') then raise exception 'Rol no válido'; end if;
 if p_id_usuario is null then
   if coalesce(length(p_password),0)<4 then raise exception 'La contraseña debe tener mínimo 4 caracteres'; end if;
   insert into sgp_usuarios(usuario,nombre,rol,password_hash,activo)
   values(lower(trim(p_usuario)),trim(p_nombre),vrol,crypt(p_password,gen_salt('bf')),coalesce(p_activo,true))
   returning id_usuario into uid;
 else
   uid:=p_id_usuario;
   update sgp_usuarios set usuario=lower(trim(p_usuario)),nombre=trim(p_nombre),rol=vrol,activo=coalesce(p_activo,true),
   password_hash=case when coalesce(p_password,'')<>'' then crypt(p_password,gen_salt('bf')) else password_hash end,actualizado_en=now()
   where id_usuario=uid;
   if not found then raise exception 'Usuario no encontrado'; end if;
 end if;
 delete from sgp_usuario_accesos where id_usuario=uid;
 insert into sgp_usuario_accesos(id_usuario,ventana,permitido) select uid,x,true from unnest(coalesce(p_accesos,array[]::text[])) x on conflict do nothing;
 return uid;
end $function$
